getAlienJoke.body:
const usedIds = ad.Session[SessionVars.Settings].pma.usedJokes;
        const availableJoke = this.petMyAlien.jokes.find((x) => !usedIds.includes(x.id));

        if (availableJoke) {
            const url = getResource(this.locale, Resource.Audio, "my-alien-friend/" + availableJoke.audio);
            return url;
        } else {
            ad.Session[SessionVars.Settings].pma.usedJokes = [];
            return this.getAlienJoke(ad)
        }
